// app.js — client bootstrap (ES module).
// Reads #app-config (JSON) generated by Jinja, imports feature modules, and
// initializes the current DOM. Safe if htmx replaces the editor or templates
// section multiple times: initializers are idempotent and delegated listeners
// are bound once on stable roots.

import { initChartInteractions, initMetricsCatalog, renderNutritionTrend, renderUnifiedChart } from './chart-interaction.js';
import { initDateNavigation } from './date-navigation.js';
import { initLevelCascade } from './level-cascade.js';
import { initEditorActions, initEditorRowSortable, syncEditorFromContent } from './editor.js';
import { initLifecycle } from './htmx-lifecycle.js';
import { ensureNutritionEditable, initNutritionEditor, refreshNutritionRowsOrder } from './nutrition-editor.js';
import { initNutritionTemplatesDnD } from './nutrition-templates.js';
import { scheduleNotices } from './notices.js';
import { initPanelCollapse } from './panel-collapse.js';
import { initNutritionRowSortable } from './row-sortable.js';
import { getCsrfToken, setAlimentoMap, setCategoriaMap, setCicloStart, setCsrfToken } from './state.js';
import { initSplits } from './splits.js';
import { initDiario } from './diario.js';
import { initEntrenoDnD, initTemplateActions, initTemplateSortable } from './templates.js';

function loadConfig() {
    const el = document.getElementById('app-config');
    if (!el) return;
    try {
        const config = JSON.parse(el.textContent);
        setCategoriaMap(config.categoria_map || {});
        setAlimentoMap(config.alimento_map || {});
        setCicloStart(config.ciclo_start || "");
        setCsrfToken(config.csrf_token || "");
    } catch (err) {
        console.error('app-config no válido', err);
    }
}

document.body.addEventListener('htmx:configRequest', function (e) {
    const token = getCsrfToken();
    if (token) e.detail.headers['X-CSRF-Token'] = token;
});

// El servidor puede refrescar #app-config vía OOB (p. ej. catálogo de
// alimentos tras un alta). Los OOB no disparan eventos por target: se
// relee tras cada petición exitosa (los swaps OOB ya están aplicados).
document.body.addEventListener('htmx:afterRequest', function (e) {
    if (e.detail && e.detail.successful) loadConfig();
});

document.addEventListener('DOMContentLoaded', function () {
    loadConfig();
    initLifecycle();
    // El bundle del dashboard (cascada, gráfica, editores) solo se inicializa
    // en la página raíz: los módulos asumen su DOM (p. ej. level-cascade hace
    // htmx.ajax a #history-section/#unified-chart, que no existen en otras
    // páginas y caerían al body, reemplazando la página completa).
    const isDashboard = !!document.getElementById('dashboard-catalog');
    const isDiario = !!document.getElementById('daily-page');
    if (isDashboard) {
        initChartInteractions();
        initMetricsCatalog();
        // La cascada restaura el estado de la URL ANTES del render inicial:
        // con selección en la URL, restoreFromURL ya pidió /grafica y SU
        // respuesta pinta la gráfica (renderizar aquí la figura sistémica
       // sería un doble render que se reemplaza al instante).
        initLevelCascade();
        const urlSelection = new URLSearchParams(location.search).get('musculos');
        if (!urlSelection) {
            renderUnifiedChart();
            renderNutritionTrend();
        }
        initDateNavigation();
        initEditorActions();
        initTemplateActions();
        initNutritionEditor();
        initNutritionRowSortable(refreshNutritionRowsOrder, ensureNutritionEditable);
        initNutritionTemplatesDnD();
        initPanelCollapse();
        syncEditorFromContent();
        initEditorRowSortable();
        initTemplateSortable();
        initEntrenoDnD();
    }
    if (isDiario) {
        initDateNavigation();
        initEditorActions();
        initTemplateActions();
        initNutritionEditor();
        initNutritionRowSortable(refreshNutritionRowsOrder, ensureNutritionEditable);
        initNutritionTemplatesDnD();
        initPanelCollapse();
        syncEditorFromContent();
        initEditorRowSortable();
        initTemplateSortable();
        initEntrenoDnD();
        initDiario();
    }
    initSplits();
    scheduleNotices();
    document.body.dataset.appReady = '1';
});
